// Package sdkgen renders the server catalogues the JavaScript SDK mirrors.
package sdkgen

import (
	"fmt"
	"reflect"
	"sort"
	"strings"

	"revoked/util"
)

const header = "// Generated by `go run ./cmd/gen-sdk` from the server's catalogues. Do not edit.\n\n"

// Files maps each generated file name to its content.
func Files() map[string]string {
	return map[string]string{
		"codes.ts":  errorCodes(),
		"events.ts": webhookEvents(),
	}
}

// Docs maps each generated documentation page, relative to the repo root,
// to its content.
func Docs() map[string]string {
	return map[string]string{
		"docs/api/errors.md": errorsPage(),
	}
}

// catalogue is every error code with its message, sorted by code.
func catalogue() (codes []string, text map[string]string) {
	text = map[string]string{}
	v := reflect.ValueOf(util.Errors)
	for i := 0; i < v.NumField(); i++ {
		if e, ok := v.Field(i).Interface().(util.AppError); ok && e.ErrorCode != "" {
			if _, dup := text[e.ErrorCode]; !dup {
				codes = append(codes, e.ErrorCode)
				text[e.ErrorCode] = e.ErrorText
			}
		}
	}
	sort.Strings(codes)
	return codes, text
}

func errorCodes() string {
	codes, _ := catalogue()

	var b strings.Builder
	b.WriteString(header)
	b.WriteString("export const ERROR_CODES = [\n")
	for _, c := range codes {
		fmt.Fprintf(&b, "  '%s',\n", c)
	}
	b.WriteString("] as const;\n\n")
	b.WriteString("/** An error code the server is known to send. */\n")
	b.WriteString("export type KnownErrorCode = (typeof ERROR_CODES)[number];\n")
	return b.String()
}

func webhookEvents() string {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("export const WEBHOOK_EVENT_TYPES = [\n")
	for _, e := range util.WebhookEventTypes {
		fmt.Fprintf(&b, "  { type: '%s', group: '%s', noisy: %t },\n", e.Type, e.Group, e.Noisy)
	}
	b.WriteString("] as const;\n\n")
	b.WriteString("/** A webhook event type the server is known to send. */\n")
	b.WriteString("export type KnownWebhookEventType = (typeof WEBHOOK_EVENT_TYPES)[number]['type'];\n\n")
	fmt.Fprintf(&b, "export const WEBHOOK_SIGNATURE_HEADER = '%s';\n", util.WebhookSignatureHeader)
	fmt.Fprintf(&b, "export const WEBHOOK_EVENT_ID_HEADER = '%s';\n", util.WebhookEventIdHeader)
	fmt.Fprintf(&b, "export const WEBHOOK_EVENT_TYPE_HEADER = '%s';\n", util.WebhookEventTypeHeader)
	fmt.Fprintf(&b, "export const WEBHOOK_SECRET_PREFIX = '%s';\n", util.WebhookSecretPrefix)
	return b.String()
}

const errorsIntro = `<!-- Generated by ` + "`go run ./cmd/gen-sdk`" + ` from util/errors.go. Do not edit. -->

# Error codes

Every failure carries a stable ` + "`code`" + `. Programs branch on the code. The
` + "`message`" + ` is written for people and may be reworded between versions.

## Shapes

The API's own routes answer with one envelope:

` + "```json" + `
{ "code": "vault_section_not_writable", "message": "This key or tool cannot write to that section.", "status": 403 }
` + "```" + `

A write to a collection that fails field validation names the fields under
` + "`data`" + `, each with its own code:

` + "```json" + `
{ "status": 400, "message": "Failed to create record.", "data": { "key": { "code": "validation_required", "message": "Cannot be blank." } } }
` + "```" + `

The OpenID Connect endpoints answer ` + "`{ \"error\": …, \"error_description\": … }`" + `,
as OAuth 2.0 specifies.

## In the JavaScript SDK

Each shape is decoded into one ` + "`RevokedError`" + `. Its ` + "`code`" + ` is the envelope's
code, the OAuth ` + "`error`" + `, or the first field's code, in that order. An answer
without any of them has the code ` + "`http_<status>`" + `, and a request that got no
answer has ` + "`network`" + ` or ` + "`timeout`" + `. ` + "`fields`" + ` holds the per-field codes.

| Status | Class |
|---|---|
| 400, 422 | ` + "`ValidationError`" + ` |
| 401 | ` + "`AuthenticationError`" + ` |
| 403 | ` + "`PermissionError`" + ` |
| 404 | ` + "`NotFoundError`" + ` |
| 409 | ` + "`ConflictError`" + ` |
| 410 | ` + "`GoneError`" + ` |
| 413 | ` + "`PayloadTooLargeError`" + ` |
| 429 | ` + "`RateLimitedError`" + `, with ` + "`retryAfter`" + ` in seconds |
| 5xx | ` + "`ServerError`" + ` |
| no answer | ` + "`NetworkError`" + `, ` + "`TimeoutError`" + ` |

` + "```ts" + `
import { RevokedError } from '@kiunke.dev/revoked';

try {
  await revoked.vault.create({ key: 'note', value: 'text', section });
} catch (error) {
  if (error instanceof RevokedError && error.code === 'vault_section_not_writable') {
    // the key may not write to that section
  }
  throw error;
}
` + "```" + `

## Codes

The status is set where an error is raised, so the same code can answer with
more than one status. A newer server can send a code missing from this list.

| Code | Message |
|---|---|
`

func errorsPage() string {
	codes, text := catalogue()
	var b strings.Builder
	b.WriteString(errorsIntro)
	for _, c := range codes {
		fmt.Fprintf(&b, "| `%s` | %s |\n", c, strings.ReplaceAll(text[c], "|", `\|`))
	}
	return b.String()
}
